-- Metadata only. Never selects rows from application/Auth/Storage objects.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'source',p.prosrc,'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig) order by p.proname) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('attach_world_publish_source','is_username_available','handle_new_user','set_updated_at')),
 'function_acl',(select jsonb_agg(jsonb_build_object('name',p.proname,'role',coalesce(r.rolname,'PUBLIC'),'privilege',x.privilege_type,'grantable',x.is_grantable) order by p.proname,coalesce(r.rolname,'PUBLIC'),x.privilege_type) from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x left join pg_roles r on r.oid=x.grantee where p.pronamespace='public'::regnamespace and p.proname in ('attach_world_publish_source','is_username_available','handle_new_user','set_updated_at')),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',replace(format_type(a.atttypid,a.atttypmod),'extensions.',''),'type_schema',(select nspname from pg_namespace where oid=(select typnamespace from pg_type where oid=a.atttypid)),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by c.relname,a.attnum) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname='public' and c.relname in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections') and a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'ddl',pg_get_constraintdef(k.oid)) order by c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid where c.relnamespace='public'::regnamespace and c.relname in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')),
 'indexes',(select jsonb_agg(jsonb_build_object('table',tablename,'name',indexname,'ddl',indexdef) order by tablename,indexname) from pg_indexes where schemaname='public' and tablename in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')),
 'acl',(select jsonb_agg(jsonb_build_object('table',c.relname,'role',r.rolname,'privilege',x.privilege_type,'grantable',x.is_grantable) order by c.relname,r.rolname,x.privilege_type) from pg_class c cross join lateral aclexplode(c.relacl) x join pg_roles r on r.oid=x.grantee where c.relnamespace='public'::regnamespace and c.relname in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')),
 'column_acl',(select jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'role',r.rolname,'privilege',x.privilege_type) order by c.relname,a.attname,r.rolname,x.privilege_type) from pg_class c join pg_attribute a on a.attrelid=c.oid cross join lateral aclexplode(a.attacl) x join pg_roles r on r.oid=x.grantee where c.relnamespace='public'::regnamespace and c.relname in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')),
 'triggers',(select jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid where not t.tgisinternal and ((c.relnamespace='public'::regnamespace and c.relname in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')) or t.tgname='on_auth_user_created')),
 'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where (schemaname='public' and tablename in ('profiles','world_publishes','world_validated_roads','world_validated_road_sections')) or (schemaname='storage' and tablename='objects' and (coalesce(qual,'')||coalesce(with_check,'')) like '%world-drive-sources%'))
) as metadata;
